const s = $('Load Client Settings').first().json;
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.inquiry_ref; });
const real = rows.filter(function (r) { return !r.is_spam && r.source !== 'test'; });
const since = $now.minus({ days: 7 });
const d = function (v) { return v ? DateTime.fromISO(String(v)) : null; };
const week = real.filter(function (r) { const t = d(r.received_at); return t && t >= since; });
const count = function (list, st) { return list.filter(function (r) { return r.status === st; }).length; };
const open = real.filter(function (r) { return r.status === 'new'; });
const overdue = open.filter(function (r) { const t = d(r.reply_due_at); return t && t < $now; });
const handled = week.filter(function (r) { return r.status !== 'new' && r.status !== 'spam'; });
const hrs = handled.map(function (r) { return d(r.status_changed_at).diff(d(r.received_at), 'hours').hours; }).filter(function (h) { return h >= 0; }).sort(function (a, b) { return a - b; });
const median = hrs.length ? hrs[Math.floor((hrs.length - 1) / 2)] : null;
const fmtH = function (h) { return h == null ? 'n/a' : (h < 1 ? Math.round(h * 60) + ' min' : (Math.round(h * 10) / 10) + ' h'); };
const esc = function (v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const topics = {};
week.forEach(function (r) { topics[r.topic || 'General inquiry'] = (topics[r.topic || 'General inquiry'] || 0) + 1; });
const topicRows = Object.keys(topics).sort(function (a, b) { return topics[b] - topics[a]; }).map(function (t) { return '<tr><td>' + esc(t) + '</td><td align="right">' + topics[t] + '</td></tr>'; }).join('');
const cell = function (label, value) { return '<td style="padding:10px 16px;border:1px solid #e4e5e3;border-radius:8px"><div style="font-size:12px;color:#5f646b;text-transform:uppercase;letter-spacing:.08em">' + label + '</div><div style="font-size:24px;color:#1f2124">' + value + '</div></td>'; };
const list = function (items) { return items.length ? '<ul>' + items.map(function (r) { return '<li>' + esc(r.name) + (r.company ? ', ' + esc(r.company) : '') + ' (' + esc(r.inquiry_ref) + ')</li>'; }).join('') + '</ul>' : '<p style="color:#5f646b">None.</p>'; };
const html = '<p>Here is your Flow summary for the week ending ' + $now.toFormat('cccc d LLLL') + '.</p>' +
  '<table cellspacing="8"><tr>' + cell('New inquiries', week.length) + cell('Won', count(week, 'won')) + cell('Lost', count(week, 'lost')) + cell('Median time to handle', fmtH(median)) + '</tr></table>' +
  '<p><b>Waiting for a reply (' + open.length + ')</b>' + (overdue.length ? ', ' + overdue.length + ' past target' : '') + '</p>' + list(open) +
  (topicRows ? '<p><b>What people asked about</b></p><table cellpadding="4">' + topicRows + '</table>' : '') +
  '<p style="color:#5f646b">Sent by Flow. Spam and test inquiries are excluded.</p>';
return [{ json: { to: s.owner_email, from: s.from_address, subject: 'Your week in Flow: ' + week.length + ' new, ' + count(week, 'won') + ' won, ' + open.length + ' waiting', html: html } }];
